__NUXT_JSONP__("/desarrollo-sostenible/eventos/ante_los_efectos_del_cambio_climatico_se_debe_impulsar_la_resiliencia_comunitaria", (function(a,b,c,d,e){return {data:[{post:{slug:"ante_los_efectos_del_cambio_climatico_se_debe_impulsar_la_resiliencia_comunitaria",title:"Ante los efectos del cambio climático se debe impulsar la resiliencia comunitaria",date:"2024-08-19T16:18:43.718Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc8a994bc-6427-4d14-bf0b-8525e7a27ba9\u002F","img-alt":"Firma convenio Red Nacional de Implementadores de la Estrategia Nacional de Comunidades Resilientes",autor:"Ethos",category:"desarrollo-sostenible",extracto:"Organizaciones de la sociedad civil y gubernamentales firmamos un convenio con el Cenapred para crear la Red Nacional de Implementadores de la Estrategia Nacional de Comunidades Resilientes.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En México, el 79% de los municipios tiene algún nivel de vulnerabilidad ante el cambio climático, de acuerdo con el Atlas de vulnerabilidad del Instituto Nacional de Ecología y Cambio Climático. Estamos hablando de la mayor parte del país, particularmente las zonas de producción de maíz blanco del norte, y las zonas más vulnerables del Sur-Sureste."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Ante este contexto, es urgente fortalecer la resiliencia desde lo local y reforzar sus capacidades para actuar frente a problemas derivados del cambio climático. Para contribuir con ello, representantes organizaciones de la sociedad civil y de organizaciones gubernamentales firmamos un convenio de colaboración con el Centro Nacional de Prevención de Desastres (Cenapred) para crear la Red Nacional de Implementadores de la Estrategia Nacional de Comunidades Resilientes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El proyecto busca sumar los esfuerzos del sector gubernamental, academia y sociedad civil para fortalecer la resiliencia comunitaria, específicamente a través de la conformación de Comités Comunitarios que compartirán herramientas y conocimientos a la población para identificar peligros, prevenir riesgos y fortalecer las capacidades locales para hacer frente a fenómenos naturales o aquellos que son producto de la actividad humana."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Participaron representantes de la Secretaría de Gobernación del estado de Puebla, la Secretaría de Medio Ambiente Desarrollo Sustentable y Ordenamiento Territorial del estado de Puebla, la Secretaría de Protección Civil del estado de Campeche, la Coordinación Estatal de Protección Civil del estado de Michoacán, la Coordinación Estatal de Protección Civil del estado de Morelos, el Instituto de Protección Civil del estado de Tabasco, la Alianza para la Seguridad Alimentaria de Baja California Sur, la Cruz Roja Mexicana, World Vision México."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fante_los_efectos_del_cambio_climatico_se_debe_impulsar_la_resiliencia_comunitaria",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2024-10-02T22:32:44.078Z")));